import React, { useEffect, useState, useCallback } from "react";

const getMovesetPath = (battleMode) =>
    battleMode === "singles"
        ? "/singles/csv_movesets/"
        : "/doubles/csv_movesets/";

export default function PokemonBuildPanel({
    clickedBuild,
    battleMode,
}) {
    const [buildData, setBuildData] = useState(null);
    const [imgSrc, setImgSrc] = useState(null);

    const [tooltip, setTooltip] = useState(null);
    const [cache, setCache] = useState({}); // ✅ FIXED

    const MOVESET_PATH = getMovesetPath(battleMode);

    const normalize = (name) =>
        name
            ?.toLowerCase()
            .replace(/[^a-z0-9\s-]/g, "")
            .trim()
            .replace(/\s+/g, "-");

    // ✅ FIX: stable function (no ESLint warning)
    const resolveImage = useCallback((name) => {
        return `/pokemon_artwork/${normalize(name)}.jpg`;
    }, []);

    const handleImgError = (e, name) => {
        const base = `/pokemon_artwork/${normalize(name)}`;
        if (e.target.src.endsWith(".jpg")) {
            e.target.src = `${base}.png`;
        } else {
            e.target.style.display = "none";
        }
    };

    const loadCSV = async (path) => {
        const res = await fetch(path);
        return await res.text();
    };

    const parseCSV = (text) =>
        text
            .trim()
            .split(/\r?\n/)
            .slice(1)
            .map((r) =>
                r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
            );

    // 🔥 FINAL FETCH FUNCTION
    const fetchInfo = async (name, category) => {
        const key = `${category}-${name}`;
        if (cache[key]) return cache[key];

        const formatted = normalize(name);

        let pokeapiUrl = "";
        let mcpEndpoint = "";

        if (category === "Moves") {
            pokeapiUrl = `https://pokeapi.co/api/v2/move/${formatted}`;
            mcpEndpoint = `http://localhost:3000/pokemon_get_move?name=${formatted}`;
        }
        else if (category === "Abilities") {
            pokeapiUrl = `https://pokeapi.co/api/v2/ability/${formatted}`;
            mcpEndpoint = `http://localhost:3000/pokemon_get_ability?name=${formatted}`;
        }
        else if (category === "Items") {
            pokeapiUrl = `https://pokeapi.co/api/v2/item/${formatted}`;
            mcpEndpoint = `http://localhost:3000/pokemon_get_item?name=${formatted}`;
        }
        else if (category === "Natures") {
            pokeapiUrl = `https://pokeapi.co/api/v2/nature/${formatted}`;
        }

        let info = "";

        // 🔹 TRY POKEAPI FIRST
        try {
            const res = await fetch(pokeapiUrl);
            const data = await res.json();

            if (category === "Moves") {
                const entry = data.effect_entries?.find(
                    (e) => e.language.name === "en"
                );
                const flavor = data.flavor_text_entries?.find(
                    (e) => e.language.name === "en"
                );

                info =
                    entry?.short_effect ||
                    entry?.effect ||
                    flavor?.flavor_text;
            }

            else if (category === "Abilities" || category === "Items") {
                const entry = data.effect_entries?.find(
                    (e) => e.language.name === "en"
                );
                info = entry?.short_effect || entry?.effect;
            }

            // ✅ NATURE FIX (robust)
            else if (category === "Natures") {
                const formatStat = (s) =>
                    s?.name
                        ?.replace("special-attack", "SP. ATK")
                        .replace("special-defense", "SP. DEF")
                        .replace("-", " ")
                        .toUpperCase();

                if (data.increased_stat && data.decreased_stat) {
                    info = `Boosts ${formatStat(
                        data.increased_stat
                    )}, lowers ${formatStat(
                        data.decreased_stat
                    )}`;
                } else {
                    info = "No stat changes";
                }
            }
        } catch (err) {
            info = "";
        }

        // 🔥 MCP FALLBACK (NOT FOR NATURES)
        if (
            (!info || info === "No description") &&
            category !== "Natures"
        ) {
            try {
                const res = await fetch(mcpEndpoint);
                const data = await res.json();

                info =
                    data?.effect ||
                    data?.description ||
                    data?.short_effect ||
                    JSON.stringify(data);
            } catch (err) {
                info = "No data found";
            }
        }

        // ✅ FINAL SAFETY (especially for natures)
        if (!info) {
            info = `${name}`;
        }

        const cleaned =
            info.replace(/\n|\f/g, " ") || "No data found";

        setCache((prev) => ({
            ...prev,
            [key]: cleaned,
        }));

        return cleaned;
    };

    // 🔥 LOAD BUILD
    useEffect(() => {
        if (!clickedBuild || !clickedBuild.sourceFile) {
            setBuildData(null);
            return;
        }

        const loadBuild = async () => {
            const text = await loadCSV(
                MOVESET_PATH + clickedBuild.sourceFile
            );

            const rows = parseCSV(text);

            const pokemonRows = rows.filter(
                (r) =>
                    normalize(r[1]) ===
                    normalize(clickedBuild.pokemon)
            );

            const grouped = {};

            for (let row of pokemonRows) {
                const category = row[2];

                const itemName =
                    category === "Stats"
                        ? row[3]
                        : row[4];

                const usage = row[5];

                if (
                    category === "Stats" &&
                    [
                        "Raw count",
                        "Avg. weight",
                        "Viability Ceiling",
                    ].includes(itemName)
                )
                    continue;

                // ✅ spreads → nature
                if (category === "Spreads") {
                    const nature = row[4]?.split(":")[0];

                    if (nature) {
                        if (!grouped["Natures"]) {
                            grouped["Natures"] = [];
                        }

                        grouped["Natures"].push({
                            name: nature,
                            usage,
                        });
                    }

                    continue;
                }

                if (!itemName) continue;

                if (!grouped[category]) {
                    grouped[category] = [];
                }

                grouped[category].push({
                    name: itemName,
                    usage,
                });
            }

            Object.keys(grouped).forEach((cat) => {
                grouped[cat] = grouped[cat]
                    .sort(
                        (a, b) =>
                            Number(b.usage) - Number(a.usage)
                    )
                    .slice(0, 5);
            });

            setImgSrc(resolveImage(clickedBuild.display));

            setBuildData({
                display: clickedBuild.display,
                month: clickedBuild.month,
                data: grouped,
            });
        };

        loadBuild();
    }, [clickedBuild, MOVESET_PATH, resolveImage]);

    if (!buildData) {
        return (
            <div style={{ padding: "10px" }}>
                Click a graph point to view build
            </div>
        );
    }

    return (
        <div style={{ position: "relative" }}>
            <img
                src={imgSrc}
                alt={buildData.display}
                onError={(e) =>
                    handleImgError(e, buildData.display)
                }
                style={{
                    width: "100px",
                    display: "block",
                    margin: "0 auto",
                }}
            />

            <h3 style={{ textAlign: "center" }}>
                {buildData.display}
            </h3>

            {Object.entries(buildData.data).map(
                ([category, items]) => (
                    <div key={category}>
                        <strong>{category}</strong>
                        <ul>
                            {items.map((item, idx) => (
                                <li
                                    key={idx}
                                    onMouseEnter={async (e) => {
                                        setTooltip({
                                            text: "Loading...",
                                            x: e.clientX,
                                            y: e.clientY,
                                        });

                                        const info =
                                            await fetchInfo(
                                                item.name,
                                                category
                                            );

                                        setTooltip({
                                            text: info,
                                            x: e.clientX,
                                            y: e.clientY,
                                        });
                                    }}
                                    onMouseLeave={() =>
                                        setTooltip(null)
                                    }
                                    style={{ cursor: "pointer" }}
                                >
                                    {item.name} ({item.usage}%)
                                </li>
                            ))}
                        </ul>
                    </div>
                )
            )}

            {tooltip && (
                <div
                    style={{
                        position: "fixed",
                        top: tooltip.y + 10,
                        left: tooltip.x + 10,
                        background: "#222",
                        color: "#fff",
                        padding: "8px",
                        borderRadius: "6px",
                        maxWidth: "300px",
                        fontSize: "12px",
                        zIndex: 9999,
                    }}
                >
                    {tooltip.text}
                </div>
            )}
        </div>
    );
}
